using Microsoft.EntityFrameworkCore;

namespace Atlas.Data;
public static class AtlasSchema {
    // Criação aditiva e idempotente. Não exclui nem altera tabelas históricas.
    // SQL Server da hospedagem já pode ter dbo.Usuarios com credenciais scrypt.
    private static readonly string[] Scripts = [
        """IF OBJECT_ID(N'dbo.Usuarios', N'U') IS NULL CREATE TABLE dbo.Usuarios (Id int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Usuarios PRIMARY KEY, Nome nvarchar(120) NOT NULL, Email nvarchar(180) NOT NULL UNIQUE, PasswordHash nvarchar(300) NOT NULL, Role varchar(20) NOT NULL DEFAULT 'ADMIN', Ativo bit NOT NULL DEFAULT 1, CriadoEm datetime2 NOT NULL DEFAULT SYSUTCDATETIME());""",
        """IF OBJECT_ID(N'dbo.AtlasFinRevenueEntries', N'U') IS NULL CREATE TABLE dbo.AtlasFinRevenueEntries (Id bigint IDENTITY(1,1) PRIMARY KEY, UserId int NOT NULL, RevenueItemName nvarchar(160) NOT NULL, Amount decimal(18,2) NOT NULL, PaymentMethod nvarchar(40) NOT NULL, [Date] date NOT NULL, ReferenceName nvarchar(160) NULL, Notes nvarchar(1000) NULL, RecurringSeriesId uniqueidentifier NULL, RecurringOccurrenceKey nvarchar(7) NULL, CreatedAt datetime2 NOT NULL);""",
        """IF OBJECT_ID(N'dbo.AtlasFinExpenseEntries', N'U') IS NULL CREATE TABLE dbo.AtlasFinExpenseEntries (Id bigint IDENTITY(1,1) PRIMARY KEY, UserId int NOT NULL, Description nvarchar(250) NOT NULL, Category nvarchar(100) NOT NULL, ExpenseType nvarchar(40) NOT NULL, Amount decimal(18,2) NOT NULL, PaymentMethod nvarchar(40) NOT NULL, [Date] date NOT NULL, DueDate date NULL, Paid bit NOT NULL, InstallmentGroupId uniqueidentifier NULL, InstallmentNumber int NULL, InstallmentTotal int NULL, RecurringSeriesId uniqueidentifier NULL, RecurringOccurrenceKey nvarchar(7) NULL, Notes nvarchar(1000) NULL, CreatedAt datetime2 NOT NULL);""",
        """IF OBJECT_ID(N'dbo.AtlasFinRecurringRevenueSeries', N'U') IS NULL CREATE TABLE dbo.AtlasFinRecurringRevenueSeries (Id uniqueidentifier PRIMARY KEY, UserId int NOT NULL, RevenueItemName nvarchar(160) NOT NULL, Amount decimal(18,2) NOT NULL, PaymentMethod nvarchar(40) NOT NULL, ReferenceName nvarchar(160) NULL, Notes nvarchar(1000) NULL, StartDate date NOT NULL, EndDate date NULL, Active bit NOT NULL, CreatedAt datetime2 NOT NULL, UpdatedAt datetime2 NOT NULL);""",
        """IF OBJECT_ID(N'dbo.AtlasFinRecurringExpenseSeries', N'U') IS NULL CREATE TABLE dbo.AtlasFinRecurringExpenseSeries (Id uniqueidentifier PRIMARY KEY, UserId int NOT NULL, Description nvarchar(250) NOT NULL, Category nvarchar(100) NOT NULL, ExpenseType nvarchar(40) NOT NULL, Amount decimal(18,2) NOT NULL, PaymentMethod nvarchar(40) NOT NULL, StartDate date NOT NULL, EndDate date NULL, Active bit NOT NULL, Notes nvarchar(1000) NULL, CreatedAt datetime2 NOT NULL, UpdatedAt datetime2 NOT NULL);""",
        """IF OBJECT_ID(N'dbo.AtlasFinRevenueItems', N'U') IS NULL CREATE TABLE dbo.AtlasFinRevenueItems (Id int IDENTITY(1,1) PRIMARY KEY, UserId int NOT NULL, Name nvarchar(160) NOT NULL, Price decimal(18,2) NOT NULL DEFAULT 0, Active bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL);""",
        """IF OBJECT_ID(N'dbo.AtlasFinGoals', N'U') IS NULL CREATE TABLE dbo.AtlasFinGoals (Id int IDENTITY(1,1) PRIMARY KEY, UserId int NOT NULL, Name nvarchar(160) NOT NULL, TargetAmount decimal(18,2) NOT NULL, CurrentAmount decimal(18,2) NOT NULL DEFAULT 0, Deadline date NULL);""",
        """IF OBJECT_ID(N'dbo.AtlasFinAuditLog', N'U') IS NULL CREATE TABLE dbo.AtlasFinAuditLog (Id bigint IDENTITY(1,1) PRIMARY KEY, UserId int NOT NULL, Action nvarchar(25) NOT NULL, Entity nvarchar(60) NOT NULL, EntityId nvarchar(70) NOT NULL, Details nvarchar(max) NULL, CreatedAt datetime2 NOT NULL);""",
        """IF OBJECT_ID(N'dbo.AtlasFinSeriesRevisions', N'U') IS NULL CREATE TABLE dbo.AtlasFinSeriesRevisions (Id bigint IDENTITY(1,1) PRIMARY KEY, UserId int NOT NULL, SeriesId uniqueidentifier NOT NULL, Kind nvarchar(10) NOT NULL, EffectiveMonth date NOT NULL, SnapshotJson nvarchar(max) NOT NULL, CreatedAt datetime2 NOT NULL);""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_AF_Revenue_UserDate' AND object_id=OBJECT_ID('dbo.AtlasFinRevenueEntries')) CREATE INDEX IX_AF_Revenue_UserDate ON dbo.AtlasFinRevenueEntries(UserId,[Date]);""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_AF_Revenue_Occurrence' AND object_id=OBJECT_ID('dbo.AtlasFinRevenueEntries')) CREATE UNIQUE INDEX UX_AF_Revenue_Occurrence ON dbo.AtlasFinRevenueEntries(RecurringSeriesId,RecurringOccurrenceKey) WHERE RecurringSeriesId IS NOT NULL;""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_AF_Expense_UserDate' AND object_id=OBJECT_ID('dbo.AtlasFinExpenseEntries')) CREATE INDEX IX_AF_Expense_UserDate ON dbo.AtlasFinExpenseEntries(UserId,[Date]);""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_AF_Expense_Occurrence' AND object_id=OBJECT_ID('dbo.AtlasFinExpenseEntries')) CREATE UNIQUE INDEX UX_AF_Expense_Occurrence ON dbo.AtlasFinExpenseEntries(RecurringSeriesId,RecurringOccurrenceKey) WHERE RecurringSeriesId IS NOT NULL;""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_AF_Expense_Installment' AND object_id=OBJECT_ID('dbo.AtlasFinExpenseEntries')) CREATE INDEX IX_AF_Expense_Installment ON dbo.AtlasFinExpenseEntries(InstallmentGroupId);""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_AF_RSeries_Owner' AND object_id=OBJECT_ID('dbo.AtlasFinRecurringRevenueSeries')) CREATE INDEX IX_AF_RSeries_Owner ON dbo.AtlasFinRecurringRevenueSeries(UserId,Active);""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_AF_ESeries_Owner' AND object_id=OBJECT_ID('dbo.AtlasFinRecurringExpenseSeries')) CREATE INDEX IX_AF_ESeries_Owner ON dbo.AtlasFinRecurringExpenseSeries(UserId,Active);""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_AF_Item_OwnerName' AND object_id=OBJECT_ID('dbo.AtlasFinRevenueItems')) CREATE UNIQUE INDEX UX_AF_Item_OwnerName ON dbo.AtlasFinRevenueItems(UserId,Name);""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_AF_Goal_OwnerDeadline' AND object_id=OBJECT_ID('dbo.AtlasFinGoals')) CREATE INDEX IX_AF_Goal_OwnerDeadline ON dbo.AtlasFinGoals(UserId,Deadline);""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_AF_Audit_UserDate' AND object_id=OBJECT_ID('dbo.AtlasFinAuditLog')) CREATE INDEX IX_AF_Audit_UserDate ON dbo.AtlasFinAuditLog(UserId,CreatedAt);""",
        """IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_AF_SeriesRevision' AND object_id=OBJECT_ID('dbo.AtlasFinSeriesRevisions')) CREATE UNIQUE INDEX UX_AF_SeriesRevision ON dbo.AtlasFinSeriesRevisions(UserId,SeriesId,Kind,EffectiveMonth);"""
    ];
    public static async Task EnsureAsync(FinanceDbContext db) {
        foreach (var command in Scripts) await db.Database.ExecuteSqlRawAsync(command);
    }
}